/* P2-BA boot ladder rung 6 — the TEXTURE CONSUMER: the texlist walk resolves
 * the sinbd logo's texture ref through the era consumer chain, end to end,
 * against the AU-loaded GVR chain. No host-side lookups: the dispatch, the
 * GVRT walk, the state/slot pool, the pixel copy are ALL the era bodies
 * generated by gen_ladder6_slices.py (contract docs/p2-gx-tex-consumer.md
 * §1.3; V-tasks in docs/p2-v-wave.md).
 *
 *   load_sin_board_image (TObjSinBoard.cpp:111) -> set_texture_name (§3#1,
 *   filename slot = pso_njs_h2g(input), AV S4 guest-stamp) ->
 *   load_texture_if_valid -> load_texture_list -> load_texture_entry
 *   (attr 0x40000000 = NJD_TEXATTR_TYPE_MEMORY -> texture_loaders[1]) ->
 *   load_texture_from_memory (filename slot -> GinjaTextureInput leg;
 *   find_gvrt_texture_chunk = the AN-era walk over the AU image bytes) ->
 *   resolve_texlist_entry / bind_texlist_texture -> create_texture_state
 *   (init_texture_from_gvr_desc -> AU upload seam -> GXGetTexBufferSize ->
 *   alloc_buffer_from_heap) -> reload_texture_slot_pixels -> era move_data.
 *
 * ORACLE: era bodies + docs/p2-tex-supply.md fixture pins (texels
 * 0xA92D59BE5839FCE5 @ heap, image 0x93B9BE4E18606D07 — the same provenance
 * anchors ladder5 S3/E4a use; clause R1 binds WAIVED COUNTS, not fixture
 * hashes). tlut-name golden: format 9 is palette => tlut KEPT 0, not -1
 * (text_803DA798.cpp:148-152 + TAdSinglePlyChrSelectGC_803DA038.cpp:26-34).
 */
#include "pso_bringup.h"
#include "ladder3_harness.h"          /* AdxfHandle/GslArchiveEntry globals  */
#include "ladder6_tex_prelude.h"      /* shadow regime + era bindings         */
#include <stdio.h>
#include <string.h>
#include <stdint.h>

/* ---- endian/hash vocabulary (ladder4_supply.o, C11 TU) ---- */
extern "C" {
uint64_t p2an_fnv1a64(const void *buf, size_t n);
}

/* ---- TObjSinBoard.cpp:37-40 .data block — arena-resident (pso_njs_h2g
 * requires the slot-space regime, AR §5; era .data lives inside guest RAM).
 * Bound in main() at arena+0x32000; the sliced bodies see the era names
 * through the prelude block macros. ---- */
SinBoardBlock *g_sinbd;

/* ---- RenderSbssGlobals.cpp / GinjaTextureTable .sbss globals -------------
 * current_render_context + active_texture_surface_count arrive as externs
 * from the era header chain; storage defined here (era .sbss zero-init). */
GinjaSceneState render_contexts[6];
GinjaSceneState *current_render_context = render_contexts;
u32 active_texture_surface_count;
/* texture_error: storage lives in the linked ladder4_gvr_glue.o (era def site
 * text_803D96A8.cpp, same as ladder5 — re-defining would collide). */
GinjaTextureState *texture_states;
s32 texture_state_count;
GinjaSurfaceState *texture_surfaces;
s32 texture_surface_count;

/* ---- the pool the consumer chain allocates states/surfaces from (1-entry
 * contract pool per §5 V3; +spare to prove find_free_texture_slot walks).
 * ARENA-RESIDENT: the texname texture-slot carries pso_njs_h2g(pool+slot)
 * handles, which round-trip only inside the guest window (AR §5). ---- */
#define L6_POOL_OFF   0x00034000u   /* arena: GinjaTextureState[4]   */
#define L6_SURF_OFF   0x00038000u   /* arena: GinjaSurfaceState[4]   */
#define L6_SINBD_OFF  0x00032000u   /* arena: SinBoardBlock          */

/* ---- DEVIATION LB-1: TQuestVmDownLoadServer::alloc -> AU-4 cache heap.
 * Era class (d) home (ChallengeRecord/NJS LOCKED, rung4 §1 rows 5-8); the
 * alloc SITE stays in the verbatim slice, storage is the locked-cache heap. */
void *TQuestVmDownLoadServer::alloc(u32 size) {
    return OSAllocFromHeap((int)locked_cache_heap_handle, size);
}

/* ---- DEVIATION LB-2: frame-pump seams (failure legs only) ---- */
static int g_pump_calls, g_lobby_rframe_calls, g_debug_prints;
void pump_frames(void) { g_pump_calls++; }
void TLobby::debug_print(const char *, ...) { g_debug_prints++; }
void TLobby::run_frame() { g_lobby_rframe_calls++; }

/* ---- DEVIATION LB-3: fail-loud stand-ins for the three loaders the sinbd
 * attr can never select (dispatch itself is the era table + era switch). ---- */
extern "C" s32 read_gvrt_file_header(NJS_TEXLIST *, s32) {
    fprintf(stderr, "L6 FATAL: read_gvrt_file_header (loader 0) called — outside contract path\n"); exit(9);
}
extern "C" s32 create_texture_from_input(NJS_TEXLIST *, s32) {
    fprintf(stderr, "L6 FATAL: create_texture_from_input (loader 2) called — outside contract path\n"); exit(9);
}
extern "C" s32 reference_texture_by_global_index(NJS_TEXLIST *, s32) {
    fprintf(stderr, "L6 FATAL: reference_texture_by_global_index (loader 3) called — outside contract path\n"); exit(9);
}

static int failures, total;
#define CHECK(cond, ...) do { total++; if (!(cond)) { failures++; \
    printf("FAIL "); printf(__VA_ARGS__); printf("\n"); } \
    else { printf("PASS "); printf(__VA_ARGS__); printf("\n"); } } while (0)

#define CACHEHEAP_START_OFF 0x01400000u
#define CACHEHEAP_SIZE      0x00010000u

int main() {
    setvbuf(stdout, 0, _IOLBF, 0);
    if (pso_bringup_install() != 0) { fprintf(stderr, "arena install failed\n"); return 2; }
    OSInit();
    DVDInit();

    /* locked-cache heap over the era OSAlloc port (AU-4 regime, same carve) */
    u8 *ch_lo = pso_arena_base + CACHEHEAP_START_OFF;
    int lh = OSCreateHeap(ch_lo, ch_lo + CACHEHEAP_SIZE);
    locked_cache_heap_handle = (u32)lh;
    CHECK(lh >= 0, "L6-H0 cache heap #%d over arena+0x%X (AU-4 carve; alloc seam site gjSystem/TObjSinBoard:112 via LB-1)", lh, CACHEHEAP_START_OFF);

    /* supply: the AU fixture bytes into the guest window (raw read is the
     * DVD-shim leg proven by ladder5 S0-S1; the CONSUMER never touches this
     * buffer except through era code + the handle math below) */
    u8 *raw = pso_arena_base + 0x30000;
    DVDFileInfo fi; memset(&fi, 0, sizeof fi);
    CHECK(DVDOpen((char *)"sinbd_tex.gvr", &fi)
          && DVDReadPrio(&fi, raw, 0x41C, 0, 2) == 0x41C
          && p2an_fnv1a64(raw, 0x41C) == 0x93b9be4e18606d07ull,
          "L6-S1 fixture in at arena+0x30000, image fnv1a64==0x93B9BE4E18606D07 (docs/p2-tex-supply.md pin — supply-side anchor, not a waived count)");

    g_sinbd = (SinBoardBlock *)(pso_arena_base + L6_SINBD_OFF);
    memset(g_sinbd, 0, sizeof *g_sinbd);
    GinjaTextureState *g_states = (GinjaTextureState *)(pso_arena_base + L6_POOL_OFF);
    GinjaSurfaceState *g_surfaces = (GinjaSurfaceState *)(pso_arena_base + L6_SURF_OFF);
    init_texture_tables(g_states, 4, g_surfaces, 4);
    CHECK(texture_states == g_states && texture_state_count == 4
          && g_states[0].tlut_name == 0xFFFFFFFFu && g_surfaces[0].id == 0xFFFFFFFFu
          && g_states[0].surface == NULL,
          "L6-P0 era init_texture_tables bound the pool: states[4]+surfaces[4], tlut 0xFFFFFFFF / id -1 pre-load (GinjaTextureTable.cpp:33-68 verbatim)");

    /* ============ THE WALK (V2): one era call drives the whole chain ============ */
    load_sin_board_image(raw, 0x41C);

    CHECK(sin_board_texture_buffer != 0
          && (u8 *)sin_board_texture_buffer >= ch_lo
          && (u8 *)sin_board_texture_buffer + 0x41C <= ch_lo + CACHEHEAP_SIZE,
          "L6-G0 load_sin_board_image: sin_board_texture_buffer=%p inside the cache heap (TQuestVmDownLoadServer::alloc leg, LB-1); era move_data copied the image", sin_board_texture_buffer);
    CHECK(signboard_texture_list.textures == pso_njs_h2g(&sin_board_texture_name)
          && signboard_texture_list.nbTexture == 1,
          "L6-G1 S4 texlist head travels as a u32 GUEST handle: list->textures==0x%08X == h2g(&sin_board_texture_name) (shadow NJS_TEXLIST.textures, AR §1)",
          signboard_texture_list.textures);
    NJS_TEXNAME *tn = NJS_HANDLE(NJS_TEXNAME, signboard_texture_list.textures);
    CHECK(tn == &sin_board_texture_name,
          "L6-G2 NJS_HANDLE(NJS_TEXNAME, list->textures) round-trips to the era TEXNAME block");
    CHECK(tn->filename == pso_njs_h2g(&sin_board_texture_surface)
          && tn->attr == 0x40000000u,
          "L6-G3 site #1 RESOLVED: set_texture_name stamped filename==h2g(&surface){0x%08X}, attr==NJD_TEXATTR_TYPE_MEMORY (GinjaTextureTable.cpp:18-28 + TObjSinBoard.cpp:119 caller — the h2g the AV §3#1 adapter demanded). Note: global_index/index 0 aliased away legitimately — NJS_TEXNAME.texaddr/texture/global_index is ONE era union slot; the bound texture handle (G4) now owns +0x8",
          tn->filename);
    CHECK(tn->texture != 0,
          "L6-G4 the memory-input leg resolved: texture_loaders[1] (era switch on attr — NOT a host lookup) bound TEXNAME.texture slot = 0x%08X (load_texture_entry verbatim dispatch, attr 0x40000000 -> loader 1, text_803DD5E0.cpp:43-64)",
          tn->texture);
    GinjaTextureState *st = NJS_HANDLE(GinjaTextureState, tn->texture);
    CHECK(st == &g_states[0],
          "L6-G5 slot 0 bound: NJS_HANDLE(GinjaTextureState, tn->texture) == texture_states+0 (set_texlist_texture h2g, §3#3 slot write)");
    CHECK(texture_states[0].surface == &g_surfaces[0]
          && g_surfaces[0].id == 0x999 && g_surfaces[0].ref_count == 1
          && texture_states[0].ref_count == 1,
          "L6-G6 create_texture_state: surface==surfaces+0, id==0x999 FROM THE ERA WALK (find_gvrt_texture_chunk read the GBIX id raw at +0x08 inside load_texture_from_memory), both ref_counts 1");
    CHECK(texture_states[0].tlut_name == 0,
          "L6-G7 format-9 PALETTE tlut KEPT 0 (NOT -1): create_texture_state :148-152 is_palette_texture_format(9) leg kept the resolve_texlist_entry tlut (texaddr 0 -> (0&0xFC000000)>>26 == 0)");
    GinjaTextureHeader *h = &g_surfaces[0].header;
    CHECK(h->format == 9 && h->width == 32 && h->height == 32 && h->size == 1024,
          "L6-G8 LB-7 offset proof: header inside surface written via the era desc (texture->p+8): {fmt %u, %ux%u, size %u} — bpp + alloc ran through the AU chain from the WALK's own desc",
          h->format, h->width, h->height, h->size);
    u32 *px = h->pixels;
    CHECK(px != 0 && (u8 *)px >= ch_lo && (u8 *)px + 1024 <= ch_lo + CACHEHEAP_SIZE,
          "L6-G9 pixels=%p heap-resident (alloc_buffer_from_heap via init_texture_from_gvr_desc)", (void *)px);
    CHECK(p2an_fnv1a64(px, 1024) == 0xa92d59be5839fce5ull,
          "L6-G10 RECEIPT — reload_texture_slot_pixels -> copy_texture_pixel_range -> copy_texture_data_and_flush(move_data, g2h(src u32 handle)) put the EXACT fixture texels in the surface: fnv1a64=0x%016llX == 0xA92D59BE5839FCE5 (the AV S4 guest-regime pixel proof)",
          p2an_fnv1a64(px, 1024));
    /* era chain behavior: the FIRST walk attempt feeds find_gvrt_texture_chunk
     * the GinjaTextureInput record (era text_803DD5E0.cpp:134 with filename=
     * input); its tag is not a GBIX/GVRT magic -> default leg stores
     * texture_error.code=4 (0x803D9D5C-:9D68), and the FALLBACK leg
     * (:136-144 input->data) carries the real walk. code==4 at the end is the
     * era residual of a resolved-in-fallback sinbd load — asserted, not hidden. */
    CHECK(texture_error.code == 4 && g_pump_calls == 0 && g_debug_prints == 0,
          "L6-G11 texture_error.code==4 = era residual of attempt-1 magic-miss on the GVC input record, fallback leg resolved (docs/p2-tex-supply L0.3 store trace); pump/debug seams untouched on the success walk (LB-2 legs provably not taken)");

    /* draw-side selection: the §3#3 subscript pattern executes for real */
    set_texture_list(&signboard_texture_list);
    set_texture_num(0);
    CHECK(current_render_context->texture_header == &g_surfaces[0].header
          && current_render_context->tlut_name == 0,
          "L6-G12 set_texture_num(0) through the double NJS_HANDLE (texlist-handle -> texture-slot -> state -> surface header): context texture_header == &surfaces[0].header, tlut 0 — the GinjaMaterial.cpp:367/388/421 subscript class resolved");
    CHECK(select_texture_by_surface_id(0x999) == 1
          && current_render_context->texture_header == &g_surfaces[0].header,
          "L6-G13 select_texture_by_surface_id(0x999)==1 (era returns 1/-1, text_803DA798.cpp:214-224) — surface found by the era find_texture_by_surface_id loop, no host-side table");

    /* double-bind idempotence: a second load shares the surface (era
     * reference_loaded_texture palette leg) */
    s32 again = load_texture_list(&signboard_texture_list);
    CHECK(again == 1 && texture_states[0].ref_count >= 1 && active_texture_surface_count == 1,
          "L6-G14 second load_texture_list==1; active_texture_surface_count==1 (shared surface leg, reference_loaded_texture :101-112) — no slot leak");

    printf("\n== P2-BA ladder6 (V1 adapters + V2 texlist walk) ==\n");
    printf("  sinbd ref 0x999 resolved by the ERA chain: TEXNAME(filename h2g)->loaders[1]->find_gvrt_texture_chunk->create_texture_state->reload_texture_slot_pixels\n");
    printf("  surface header {9,32,32,1024} pixels fnv1a64=0xA92D59BE5839FCE5 == AU heap texels\n");
    printf("== P2-BA ladder6: %d/%d PASS ==\n", total - failures, total);
    return failures == 0 ? 0 : 1;
}
